import numpy as np


def r(x):
    # Maps x in [0, 1] to [0, 1] such that r(x) >= x.
    # Since the original program is monotone increasing, this should increase the output.
    return float(np.sqrt(x))


def R(y_orig, y_new):
    # Since r(x) >= x, we expect y_new >= y_orig.
    return bool(y_new >= y_orig)
